namespace ghidra.program.database.mem;



using db;
using ghidra.program.model.mem;

/**
 * Implementation of SubMemoryBlock for uninitialized blocks.
 */
class UninitializedSubMemoryBlock : SubMemoryBlock {

	UninitializedSubMemoryBlock(MemoryMapDBAdapter adapter, DBRecord record) : base(adapter, record)
    {
	}

	/* @Override */
	public bool isInitialized() {
		return false;
	}

	/* @Override */
	public byte getByte(long offset)
    {
		if (offset < subBlockOffset || offset >= subBlockOffset + subBlockLength) {
			throw new IllegalArgumentException(
				"Offset " + offset + "is out of bounds. Should be in [" + subBlockOffset + "," +
					(subBlockOffset + subBlockLength - 1));
		}
		throw new MemoryAccessException("Attempted to read from uninitialized block");
	}

	/* @Override */
	public int getBytes(long offset, byte[] b, int off, int len)
    {
		throw new MemoryAccessException("Attempted to read from uninitialized block");
	}

	/* @Override */
	public void putByte(long offset, byte b)
    {
		throw new MemoryAccessException("Attempted to write to an uninitialized block");
	}

	/* @Override */
	public int putBytes(long offset, byte[] b, int off, int len)
    {
		throw new MemoryAccessException("Attempted to write to an uninitialized block");
	}

	/* @Override */
	protected bool join(SubMemoryBlock block)
    {
		if (!(block is UninitializedSubMemoryBlock)) {
			return false;
		}
		setLength(subBlockLength + block.subBlockLength);
		adapter.deleteSubBlock(block.record.getKey());
		return true;
	}

